/** Geometría común de una brida (mm). */
export interface FlangeDims {
  std: string; size: string; rating: string; pipeOD: number;
  D: number; tf: number; hubX: number; hubA: number; Y: number; ySO: number;
  rf: number; rfH: number; rfIncluded: boolean; bc: number; n: number; hole: number; bolt: string;
}
const boltIn = (holeIn: number) => {
  const e = Math.round((holeIn - 0.125) * 8); // octavos de pulgada
  const w = Math.floor(e / 8), f = e % 8;
  const frac = f ? (f % 4 === 0 ? `${f / 4}/2` : f % 2 === 0 ? `${f / 2}/4` : `${f}/8`) : '';
  return `${w ? w : ''}${w && frac ? '-' : ''}${frac}"`;
};

export const B165_CLASSES = [150, 300, 400, 600, 900, 1500, 2500];
export function b165(cls: number, nps: string): FlangeDims | null {
  const row = B165[cls]?.find((r) => r[0] === nps); if (!row) return null;
  const [, O, tf, X, Y, R, BC, n, h] = row;
  const ySO = SO_Y[cls]?.[nps] ?? (SO_Y[cls <= 400 ? 300 : 600]?.[nps] ? tf + (Y - tf) * 0.45 : tf + (Y - tf) * 0.45);
  return {
    std: 'ASME B16.5', size: nps, rating: `Clase ${cls}`, pipeOD: pipeOD(nps),
    // B16.5: t_f no incluye la cara realzada; Y la incluye en clases 150/300 y no en 400 y superiores
    D: r1(O * IN), tf: r1(tf * IN), hubX: r1(X * IN), hubA: pipeOD(nps), Y: r1(Y * IN + (cls >= 400 ? 6.4 : 0)), ySO: r1(ySO * IN + (cls >= 400 ? 6.4 : 0)),
    rf: r1(R * IN), rfH: cls <= 300 ? 1.6 : 6.4, rfIncluded: false, bc: r1(BC * IN), n, hole: r1(h * IN), bolt: boltIn(h),
  };
}
export const b165Sizes = (cls: number) => (B165[cls] ?? []).map((r) => r[0]);

